const items = $input.all();
// Drop empty-json items (alwaysOutputData emits {} when the sheet is empty)
const rows = items.map(i => i.json || {}).filter(r => Object.keys(r).length > 0 && (r.Email || r.Name || r.Status));

const now = new Date();
const pad = (n) => String(n).padStart(2, "0");
const reportDate = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const statuses = ["New", "Contacted", "Converted", "Needs Human Response", "Lost"];
const statusCounts = {};
for (const s of statuses) statusCounts[s] = 0;

let total = 0;
let newThisWeek = 0;
let day3Sent = 0;
let day5Sent = 0;
let converted = 0;

const yes = (v) => String(v).trim().toLowerCase() === "yes";

for (const r of rows) {
  total++;
  const st = String(r.Status || "").trim();
  if (statusCounts[st] !== undefined) statusCounts[st]++;
  const created = new Date(r.CreatedDate);
  if (!isNaN(created.getTime()) && created >= weekAgo) newThisWeek++;
  if (yes(r.Day3)) day3Sent++;
  if (yes(r.Day5)) day5Sent++;
  if (yes(r.Converted) || st === "Converted") converted++;
}

const convRate = total > 0 ? ((converted / total) * 100).toFixed(1) : "0.0";

const statusRows = statuses
  .map(s => `<tr><td style="padding:4px 12px;border:1px solid #ddd;">${s}</td><td style="padding:4px 12px;border:1px solid #ddd;text-align:right;">${statusCounts[s]}</td></tr>`)
  .join("");

const html = `<h2>Weekly Lead Report — ${reportDate}</h2>
<p>Summary of CRM activity for the past week.</p>
<ul>
  <li><strong>Total leads:</strong> ${total}</li>
  <li><strong>New leads this week:</strong> ${newThisWeek}</li>
  <li><strong>Day 3 follow-ups sent:</strong> ${day3Sent}</li>
  <li><strong>Day 5 follow-ups sent:</strong> ${day5Sent}</li>
  <li><strong>Converted:</strong> ${converted} (${convRate}% conversion rate)</li>
</ul>
<h3>Leads by status</h3>
<table style="border-collapse:collapse;">
  <tr><th style="padding:4px 12px;border:1px solid #ddd;text-align:left;">Status</th><th style="padding:4px 12px;border:1px solid #ddd;">Count</th></tr>
  ${statusRows}
</table>`;

return [{ json: { reportDate, total, newThisWeek, day3Sent, day5Sent, converted, convRate, statusCounts, html } }];
